mapper.select:
SELECT g.game_id, g.game_code, g.game_name, g.category, gp.provider_code, g.thumbnail_url, g.play_count, g.enabled, g.create_time FROM t_game g JOIN t_game_provider gp ON g.provider_id = gp.provider_id
g.deleted = FALSE
AND (g.game_name ILIKE CONCAT('%', #{query.keyword}, '%') OR g.game_code ILIKE CONCAT('%', #{query.keyword}, '%'))
AND g.category = #{query.category}
AND gp.provider_code = #{query.providerCode}
AND g.enabled = #{query.enabled}
ORDER BY g.play_count DESC, g.game_id DESC
